        "New tax reform proposal will provide tax credits for renewable energy investments"
    ]

    // Filter the potential updates based on the demographics
    let filteredUpdates = potentialUpdates.filter { update in
        // Check if the update is relevant to the demographics
        let relevantUpdate = update.contains("low-income families") || update.contains("high-income earners") || update.contains("luxury items") || update.contains("renewable energy")

        // Check if the update is positive or negative based on the demographics
        let positiveUpdate = update.contains("benefit") || update.contains("increase") || update.contains("eliminate") || update.contains("credits")

        // Return true if the update is relevant and positive, false otherwise
        return relevantUpdate && positiveUpdate
    }

    // Return the filtered updates
    return filteredUpdates
}

